"id":"geonames:9977407","city":"Ganguwa","region":"Haryana","countryCode":"IN","country":"India","latitude":29.11,"longitude":75.7,"population":25847,"aliases":["ganguwa","gangwa"]},{"id":"geonames:997751","city":"Harrismith","region":"Free State","countryCode":"ZA","country":"South Africa","latitude":-28.27,"longitude":29.13,"population":33390,"aliases":["42nd hill","garrismit","harrismith","hrs","гаррисмит"]},{"id":"geonames:998082","city":"Hammanskraal","region":"North West","countryCode":"ZA","country":"South Africa","latitude":-25.41,"longitude":28.29,"population":112950,"aliases":["hammanskraal","khammanskraal","хамманскраал"]},{"id":"geonames:9983718","city":"Cheremushky","region":"Odesa","countryCode":"UA","country":"Ukraine","latitude":46.43,"longitude":30.71,"population":120000,"aliases":["cheremushki","cheremushky","черемушки"]},{"id":"geonames:9985580","city":"Gulgam","region":"Jammu and Kashmir","countryCode":"IN","country":"India","latitude":34.55,"longitude":74.22,"population":15587,"aliases":["gulgam","trehgam"]},{"id":"geonames:9988213","city":"Zhonghe","region":"Yunnan","countryCode":"CN","country":"China","latitude":25.06,"longitude":98.4,"population":37682,"aliases":["zhong he","zhonghe","中河"]},{"id":"geonames:999602","city":"Groot-Brakrivier","region":"Western Cape","countryCode":"ZA","country":"South Africa","latitude":-34.04,"longitude":22.23,"population":18008,"aliases":["great brak river","groot brakrivier"]}]'::jsonb)
  as p(id text, city text, region text, "countryCode" text, country text,
    latitude double precision, longitude double precision, population bigint, aliases jsonb);
insert into public.prayer_places(id, city, region, country_code, country, latitude, longitude, population, search_text)
select id, city, region, "countryCode", country, latitude, longitude, population,
  public.prayer_location_key(concat_ws(' ', city, region, "countryCode", country,
    case "countryCode" when 'GB' then 'UK Britain Great Britain England Scotland Wales Northern Ireland'
      when 'US' then 'USA United States of America' when 'AE' then 'UAE' else '' end,
    (select string_agg(value, ' ') from jsonb_array_elements_text(aliases))))
from oratio_place_seed;
insert into public.prayer_place_aliases(place_id, country_code, alias_key)
select p.id, p."countryCode", a.value from oratio_place_seed p
cross join lateral jsonb_array_elements_text(p.aliases) a;
drop table oratio_place_seed;
-- Reconcile old names without deleting prayers, changing IDs, audiences or expiry.
-- The trigger strips unverified coordinates and location from private prayers.
update public.prayer_requests set location_place_id = null;
notify pgrst, 'reload schema';
